          "code": "import numpy as np\nfrom sklearn.metrics import adjusted_rand_score\nfrom sklearn.mixture import GaussianMixture\n\nrng = np.random.default_rng(2313)\nX = np.vstack([\n    rng.multivariate_normal([-3.0, -1.0], [[0.9, 0.5], [0.5, 0.7]], size=180),\n    rng.multivariate_normal([0.2, 2.2], [[0.7, -0.3], [-0.3, 0.8]], size=150),\n    rng.multivariate_normal([3.4, -0.4], [[1.1, 0.4], [0.4, 0.6]], size=170),\n])\n\ndef fit_canonical_gmm(X_in: np.ndarray, k: int, seed: int) -> tuple[GaussianMixture, np.ndarray, np.ndarray]:\n    \"\"\"Latih GMM lalu kunci urutan ID komponen berdasarkan mean fitur-0 secara menaik.\"\"\"\n    model = GaussianMixture(n_components=k, covariance_type=\"full\", n_init=3, random_state=seed).fit(X_in)\n    raw_labels = model.predict(X_in)\n    # Permutasi kanonis berdasarkan sumbu-0 sentroid agar ID stabil lintas retraining\n    order = np.argsort(model.means_[:, 0])\n    inv_order = np.empty_like(order)\n    inv_order[order] = np.arange(k)\n    canon_labels = inv_order[raw_labels]\n    return model, raw_labels, canon_labels\n\nref_model, ref_raw, ref_canon = fit_canonical_gmm(X, k=3, seed=10)\n\nprint(\"=== 1. Audit Label Switching (K! = 6 Permutasi) Lintas Retraining & Penguncian Kanonis ===\")\nprint(\"Seed | Avg Log-Lik | Raw ID Match vs Seed-10 | ARI vs Seed-10 | Canonical ID Match\")\nprint(\"-\" * 82)\nfor seed in [10, 21, 37, 55, 99]:\n    m, raw_l, canon_l = fit_canonical_gmm(X, k=3, seed=seed)\n    raw_match = 100.0 * float(np.mean(raw_l == ref_raw))\n    ari = float(adjusted_rand_score(ref_raw, raw_l))\n    canon_match = 100.0 * float(np.mean(canon_l == ref_canon))\n    print(f\"{seed:4d} | {m.score(X):11.5f} | {raw_match:22.1f}% | {ari:14.4f} | {canon_match:17.1f}%\")\n\n# 2) Audit Kapabilitas Generatif GMM: Sampling Data Sintetis p(x)\nX_syn, z_syn = ref_model.sample(n_samples=600)\nmean_err = float(np.linalg.norm(X.mean(axis=0) - X_syn.mean(axis=0)))\ncov_err = float(np.linalg.norm(np.cov(X, rowvar=False) - np.cov(X_syn, rowvar=False), ord=\"fro\"))\nsyn_counts = np.bincount(z_syn, minlength=3).tolist()\n\nprint(\"\\n=== 2. Audit Kualitas Sampling Generatif gmm.sample(600) ===\")\nprint(f\"Distribusi Komponen Sintetis  : {syn_counts} (bobot latih: {np.round(ref_model.weights_, 3).tolist()})\")\nprint(f\"Galat L2 Mean Global          : {mean_err:.4f}\")\nprint(f\"Galat Frobenius Kovarians     : {cov_err:.4f}\")",
          "expectedOutput": "=== 1. Audit Label Switching (K! = 6 Permutasi) Lintas Retraining & Penguncian Kanonis ===\nSeed | Avg Log-Lik | Raw ID Match vs Seed-10 | ARI vs Seed-10 | Canonical ID Match\n----------------------------------------------------------------------------------\n  10 |    -3.56015 |                  100.0% |         1.0000 |             100.0%\n  21 |    -3.56015 |                   30.0% |         1.0000 |             100.0%\n  37 |    -3.56015 |                    0.0% |         1.0000 |             100.0%\n  55 |    -3.56015 |                   30.0% |         1.0000 |             100.0%\n  99 |    -3.56015 |                  100.0% |         1.0000 |             100.0%\n\n=== 2. Audit Kualitas Sampling Generatif gmm.sample(600) ===\nDistribusi Komponen Sintetis  : [202, 206, 192] (bobot latih: [0.338, 0.36, 0.301])\nGalat L2 Mean Global          : 0.0485\nGalat Frobenius Kovarians     : 0.7792",
          "actualOutput": "=== 1. Audit Label Switching (K! = 6 Permutasi) Lintas Retraining & Penguncian Kanonis ===\nSeed | Avg Log-Lik | Raw ID Match vs Seed-10 | ARI vs Seed-10 | Canonical ID Match\n----------------------------------------------------------------------------------\n  10 |    -3.56015 |                  100.0% |         1.0000 |             100.0%\n  21 |    -3.56015 |                   30.0% |         1.0000 |             100.0%\n  37 |    -3.56015 |                    0.0% |         1.0000 |             100.0%\n  55 |    -3.56015 |                   30.0% |         1.0000 |             100.0%\n  99 |    -3.56015 |                  100.0% |         1.0000 |             100.0%\n\n=== 2. Audit Kualitas Sampling Generatif gmm.sample(600) ===\nDistribusi Komponen Sintetis  : [202, 206, 192] (bobot latih: [0.338, 0.36, 0.301])\nGalat L2 Mean Global          : 0.0485\nGalat Frobenius Kovarians     : 0.7792",
