          "code": "import numpy as np\nfrom scipy.linalg import cholesky, solve_triangular\nfrom scipy.special import logsumexp\nfrom sklearn.metrics import adjusted_rand_score\nfrom sklearn.mixture import GaussianMixture\n\nrng = np.random.default_rng(232)\n\n# Bangkitkan 3 klaster Gaussian tumpang tindih moderat (N=450, d=3)\nX = np.vstack([\n    rng.multivariate_normal([-2.0, 0.0, 0.5], [[1.2, 0.6, 0.2], [0.6, 1.0, 0.1], [0.2, 0.1, 0.8]], size=160),\n    rng.multivariate_normal([1.6, 1.8, -0.5], [[0.9, -0.4, 0.2], [-0.4, 1.1, 0.3], [0.2, 0.3, 0.9]], size=150),\n    rng.multivariate_normal([1.8, -1.9, 1.4], [[1.0, 0.3, -0.4], [0.3, 0.8, 0.1], [-0.4, 0.1, 1.2]], size=140),\n])\ny_true = np.array([0] * 160 + [1] * 150 + [2] * 140)\n\ndef compute_log_joint(X_in: np.ndarray, pis: np.ndarray, mus: np.ndarray, covs: np.ndarray) -> np.ndarray:\n    \"\"\"Hitung matriks N x K berisi log(pi_k * N(x_i | mu_k, cov_k)) lewat Cholesky.\"\"\"\n    n, d = X_in.shape\n    k = len(pis)\n    log_joint = np.empty((n, k), dtype=float)\n    const = d * np.log(2.0 * np.pi)\n    for j in range(k):\n        L = cholesky(covs[j], lower=True)\n        log_det = 2.0 * np.sum(np.log(np.diag(L)))\n        sol = solve_triangular(L, (X_in - mus[j]).T, lower=True)\n        mahal_sq = np.sum(sol ** 2, axis=0)\n        log_joint[:, j] = np.log(pis[j]) - 0.5 * (const + log_det + mahal_sq)\n    return log_joint\n\ndef elbo_value(log_joint: np.ndarray, gamma: np.ndarray) -> float:\n    \"\"\"Hitung rata-rata ELBO per sampel: (1/N) * (E_q[log p(X,Z|theta)] - E_q[log q(Z)]).\"\"\"\n    g_safe = np.clip(gamma, 1e-300, 1.0)\n    expected_complete = float(np.sum(gamma * log_joint))\n    entropy = float(-np.sum(gamma * np.log(g_safe)))\n    return (expected_complete + entropy) / log_joint.shape[0]\n\ndef fit_em_gmm_stable(X_in: np.ndarray, k: int, max_iter: int = 40, tol: float = 1e-6, reg_covar: float = 1e-6):\n    n, d = X_in.shape\n    init_idx = np.array([0, 180, 340])  # Titik awal deterministik\n    pis = np.full(k, 1.0 / k)\n    mus = X_in[init_idx].copy()\n    covs = np.array([np.cov(X_in, rowvar=False) + reg_covar * np.eye(d) for _ in range(k)])\n\n    trace = []\n    for it in range(1, max_iter + 1):\n        # Evaluasi log-likelihood sebelum E-step\n        lj_before = compute_log_joint(X_in, pis, mus, covs)\n        log_px_before = logsumexp(lj_before, axis=1)\n        ll_before = float(np.mean(log_px_before))\n\n        # E-Step: q^(t+1)(z_i=k) = p(z_i=k | x_i, theta^(t)) -> menihilkan KL(q || p)\n        gamma = np.exp(lj_before - log_px_before[:, None])\n        elbo_e = elbo_value(lj_before, gamma)\n        kl_e = ll_before - elbo_e\n\n        # M-Step: solusi bentuk tertutup untuk pi_k, mu_k, Sigma_k\n        nk = np.sum(gamma, axis=0)\n        pis = nk / n\n        mus = (gamma.T @ X_in) / nk[:, None]\n        for j in range(k):\n            diff = X_in - mus[j]\n            covs[j] = (diff.T @ (diff * gamma[:, j : j + 1])) / nk[j] + reg_covar * np.eye(d)\n\n        # Evaluasi ELBO dan Log-Likelihood pasca M-Step\n        lj_after = compute_log_joint(X_in, pis, mus, covs)\n        elbo_m = elbo_value(lj_after, gamma)\n        ll_after = float(np.mean(logsumexp(lj_after, axis=1)))\n        trace.append((it, ll_before, elbo_e, kl_e, elbo_m, ll_after))\n\n        if abs(ll_after - ll_before) < tol:\n            break\n    return pis, mus, covs, gamma, trace\n\npis, mus, covs, gamma, trace = fit_em_gmm_stable(X, k=3)\ndeltas = [row[5] - row[1] for row in trace]\nmax_kl_e = max(abs(row[3]) for row in trace)\nelbo_chain_ok = all((row[5] >= row[4] - 1e-12) and (row[4] >= row[2] - 1e-12) for row in trace)\n\nsk_gmm = GaussianMixture(n_components=3, covariance_type=\"full\", n_init=5, random_state=42).fit(X)\nari_our = float(adjusted_rand_score(y_true, np.argmax(gamma, axis=1)))\nari_sk = float(adjusted_rand_score(y_true, sk_gmm.predict(X)))\n\nprint(\"=== 1. Jejak Bukti Monotonisitas EM: ll_after >= ELBO_M >= ELBO_E == ll_before ===\")\nprint(\"Iter | ll_before |  ELBO_E   |  KL_after_E |  ELBO_M   | ll_after  |  Delta LL\")\nprint(\"-\" * 82)\nfor row in trace[:5] + [trace[-1]]:\n    it, ll0, ee, kl, em, ll1 = row\n    print(f\"{it:4d} | {ll0:9.5f} | {ee:9.5f} | {kl:11.2e} | {em:9.5f} | {ll1:9.5f} | {ll1 - ll0:+9.6f}\")\n\nprint(\"\\n=== 2. Audit Ketat Teorema Dempster-Laird-Rubin (1977) & Komparasi Scikit-Learn ===\")\nprint(f\"Total Iterasi Konvergen     : {len(trace)}\")\nprint(f\"Min Delta LL (harus >= 0)   : {min(deltas):+.2e}\")\nprint(f\"Max |KL pasca E-Step|       : {max_kl_e:.2e}\")\nprint(f\"Rantai ll >= ELBO_M >= LL_0 : {elbo_chain_ok}\")\nprint(f\"Final Avg LL (Scratch vs SK): {trace[-1][5]:.6f} vs {sk_gmm.score(X):.6f}\")\nprint(f\"ARI (Scratch vs Sklearn)    : {ari_our:.4f} vs {ari_sk:.4f}\")",
          "expectedOutput": "=== 1. Jejak Bukti Monotonisitas EM: ll_after >= ELBO_M >= ELBO_E == ll_before ===\nIter | ll_before |  ELBO_E   |  KL_after_E |  ELBO_M   | ll_after  |  Delta LL\n----------------------------------------------------------------------------------\n   1 |  -6.47171 |  -6.47171 |    0.00e+00 |  -5.51302 |  -5.45689 | +1.014822\n   2 |  -5.45689 |  -5.45689 |    0.00e+00 |  -5.39817 |  -5.35784 | +0.099042\n   3 |  -5.35784 |  -5.35784 |    8.88e-16 |  -5.32147 |  -5.29938 | +0.058459\n   4 |  -5.29938 |  -5.29938 |    0.00e+00 |  -5.27919 |  -5.26153 | +0.037851\n   5 |  -5.26153 |  -5.26153 |    0.00e+00 |  -5.24218 |  -5.22410 | +0.037431\n  24 |  -5.10038 |  -5.10038 |    0.00e+00 |  -5.10038 |  -5.10038 | +0.000001\n\n=== 2. Audit Ketat Teorema Dempster-Laird-Rubin (1977) & Komparasi Scikit-Learn ===\nTotal Iterasi Konvergen     : 24\nMin Delta LL (harus >= 0)   : +6.07e-07\nMax |KL pasca E-Step|       : 8.88e-16\nRantai ll >= ELBO_M >= LL_0 : True\nFinal Avg LL (Scratch vs SK): -5.100382 vs -5.100467\nARI (Scratch vs Sklearn)    : 0.9156 vs 0.9279",
          "actualOutput": "=== 1. Jejak Bukti Monotonisitas EM: ll_after >= ELBO_M >= ELBO_E == ll_before ===\nIter | ll_before |  ELBO_E   |  KL_after_E |  ELBO_M   | ll_after  |  Delta LL\n----------------------------------------------------------------------------------\n   1 |  -6.47171 |  -6.47171 |    0.00e+00 |  -5.51302 |  -5.45689 | +1.014822\n   2 |  -5.45689 |  -5.45689 |    0.00e+00 |  -5.39817 |  -5.35784 | +0.099042\n   3 |  -5.35784 |  -5.35784 |    8.88e-16 |  -5.32147 |  -5.29938 | +0.058459\n   4 |  -5.29938 |  -5.29938 |    0.00e+00 |  -5.27919 |  -5.26153 | +0.037851\n   5 |  -5.26153 |  -5.26153 |    0.00e+00 |  -5.24218 |  -5.22410 | +0.037431\n  24 |  -5.10038 |  -5.10038 |    0.00e+00 |  -5.10038 |  -5.10038 | +0.000001\n\n=== 2. Audit Ketat Teorema Dempster-Laird-Rubin (1977) & Komparasi Scikit-Learn ===\nTotal Iterasi Konvergen     : 24\nMin Delta LL (harus >= 0)   : +6.07e-07\nMax |KL pasca E-Step|       : 8.88e-16\nRantai ll >= ELBO_M >= LL_0 : True\nFinal Avg LL (Scratch vs SK): -5.100382 vs -5.100467\nARI (Scratch vs Sklearn)    : 0.9156 vs 0.9279",
