          "code": "import numpy as np\nfrom sklearn.metrics import adjusted_rand_score\nfrom sklearn.mixture import GaussianMixture\n\nrng = np.random.default_rng(2322)\n\n# Dataset menantang: 6 klaster 3D dengan pasangan berdekatan & ukuran tidak seimbang (rawan local optima)\ncenters = [\n    [-3.2, 0.0, 0.0],\n    [-1.4, 0.8, 0.4],\n    [0.0, 3.0, -1.0],\n    [2.6, 2.2, 1.2],\n    [3.5, -1.8, 0.0],\n    [-0.5, -3.2, -1.4],\n]\nsizes = [75, 45, 65, 40, 75, 60]\nX = np.vstack([rng.normal(c, 0.65, size=(s, 3)) for c, s in zip(centers, sizes)])\ny_true = np.concatenate([np.full(s, idx) for idx, s in enumerate(sizes)])\n\nprint(\"=== Benchmark Inisialisasi EM & Multi-Start n_init (6 Uji Seed Berbeda) ===\")\nprint(\"Strategi Inisialisasi    | n_init | Min LL   | Med LL   | Max LL   | Std LL | Mean Iter | Med ARI\")\nprint(\"-\" * 98)\nconfigs = [\n    (\"random\", 1),\n    (\"random_from_data\", 1),\n    (\"kmeans\", 1),\n    (\"k-means++\", 1),\n    (\"k-means++\", 4),\n]\nfor init_p, n_init in configs:\n    lls, iters, aris = [], [], []\n    for seed in range(6):\n        m = GaussianMixture(\n            n_components=6,\n            covariance_type=\"full\",\n            init_params=init_p,\n            n_init=n_init,\n            max_iter=120,\n            random_state=100 + seed,\n        ).fit(X)\n        lls.append(float(m.score(X)))\n        iters.append(int(m.n_iter_))\n        aris.append(float(adjusted_rand_score(y_true, m.predict(X))))\n    print(\n        f\"{init_p:24s} | {n_init:6d} | {min(lls):8.4f} | {np.median(lls):8.4f} | \"\n        f\"{max(lls):8.4f} | {np.std(lls):6.4f} | {np.mean(iters):9.1f} | {np.median(aris):7.4f}\"\n    )",
          "expectedOutput": "=== Benchmark Inisialisasi EM & Multi-Start n_init (6 Uji Seed Berbeda) ===\nStrategi Inisialisasi    | n_init | Min LL   | Med LL   | Max LL   | Std LL | Mean Iter | Med ARI\n--------------------------------------------------------------------------------------------------\nrandom                   |      1 |  -4.9567 |  -4.7681 |  -4.6323 | 0.1228 |      55.2 |  0.6552\nrandom_from_data         |      1 |  -4.7337 |  -4.6589 |  -4.6225 | 0.0449 |      16.7 |  0.7625\nkmeans                   |      1 |  -4.6307 |  -4.6226 |  -4.6226 | 0.0030 |       3.3 |  0.9248\nk-means++                |      1 |  -4.6911 |  -4.6285 |  -4.6226 | 0.0242 |       7.2 |  0.8252\nk-means++                |      4 |  -4.6248 |  -4.6228 |  -4.6226 | 0.0008 |       6.8 |  0.8976",
          "actualOutput": "=== Benchmark Inisialisasi EM & Multi-Start n_init (6 Uji Seed Berbeda) ===\nStrategi Inisialisasi    | n_init | Min LL   | Med LL   | Max LL   | Std LL | Mean Iter | Med ARI\n--------------------------------------------------------------------------------------------------\nrandom                   |      1 |  -4.9567 |  -4.7681 |  -4.6323 | 0.1228 |      55.2 |  0.6552\nrandom_from_data         |      1 |  -4.7337 |  -4.6589 |  -4.6225 | 0.0449 |      16.7 |  0.7625\nkmeans                   |      1 |  -4.6307 |  -4.6226 |  -4.6226 | 0.0030 |       3.3 |  0.9248\nk-means++                |      1 |  -4.6911 |  -4.6285 |  -4.6226 | 0.0242 |       7.2 |  0.8252\nk-means++                |      4 |  -4.6248 |  -4.6228 |  -4.6226 | 0.0008 |       6.8 |  0.8976",
