          "id": "code-ml-23-2-ch23_2_diag",
          "title": "Production Audit: Catastrophic Underflow NaN pada EM Naif (d=10..500) & Perlambatan High-Overlap",
          "language": "python",
          "filename": "23_2_underflow_nan_and_overlap_audit.py",
          "code": "import numpy as np\nfrom scipy.linalg import cholesky, solve_triangular\nfrom scipy.special import logsumexp\nfrom sklearn.mixture import GaussianMixture\n\nrng = np.random.default_rng(2323)\n\nprint(\"=== 1. Audit Catastrophic Floating-Point Underflow: EM Naif vs Log-Sum-Exp + Cholesky ===\")\nprint(\"Dimensi d | Min log p(x,z) | Naive exp() NaN (%) | Stable LSE NaN (%) | Max |sum(gamma)-1|\")\nprint(\"-\" * 90)\nfor d in [10, 60, 150, 300, 450]:\n    X_d = rng.normal(0.0, 1.5, size=(80, d))\n    mus_d = np.vstack([np.full(d, -0.3), np.full(d, 0.3)])\n    covs_d = np.array([1.2 * np.eye(d), 1.2 * np.eye(d)])\n    pis_d = np.array([0.5, 0.5])\n\n    # Hitung log joint via Cholesky\n    log_j = np.empty((80, 2), dtype=float)\n    for j in range(2):\n        L = cholesky(covs_d[j], lower=True)\n        log_det = 2.0 * np.sum(np.log(np.diag(L)))\n        sol = solve_triangular(L, (X_d - mus_d[j]).T, lower=True)\n        log_j[:, j] = np.log(pis_d[j]) - 0.5 * (d * np.log(2.0 * np.pi) + log_det + np.sum(sol ** 2, axis=0))\n\n    # Naive E-Step: langsung np.exp(log_j) -> underflow ke 0.0 -> 0.0 / 0.0 = NaN!\n    with np.errstate(divide=\"ignore\", invalid=\"ignore\"):\n        w_naive = np.exp(log_j)\n        g_naive = w_naive / np.sum(w_naive, axis=1, keepdims=True)\n    nan_naive = 100.0 * float(np.mean(np.any(np.isnan(g_naive), axis=1)))\n\n    # Stable E-Step: Log-Sum-Exp\n    lse = logsumexp(log_j, axis=1, keepdims=True)\n    g_stable = np.exp(log_j - lse)\n    nan_stable = 100.0 * float(np.mean(np.any(np.isnan(g_stable), axis=1)))\n    row_err = float(np.max(np.abs(np.sum(g_stable, axis=1) - 1.0)))\n    print(f\"{d:9d} | {np.min(log_j):14.1f} | {nan_naive:18.1f}% | {nan_stable:17.1f}% | {row_err:18.2e}\")\n\nprint(\"\\n=== 2. Audit Perlambatan Laju Konvergensi EM pada Klaster High-Overlap ===\")\nprint(\"Separasi (Delta_mu / sigma) | n_iter (tol=1e-4) | Converged (max=150) | Final Avg LL\")\nprint(\"-\" * 84)\nfor sep in [4.0, 2.5, 1.6, 1.0, 0.6]:\n    X_ov = np.vstack([\n        rng.normal([0.0, 0.0], 1.0, size=(200, 2)),\n        rng.normal([sep, 0.0], 1.0, size=(200, 2)),\n    ])\n    m_ov = GaussianMixture(\n        n_components=2, covariance_type=\"full\", tol=1e-4, max_iter=150, n_init=2, random_state=42\n    ).fit(X_ov)\n    print(f\"{sep:27.1f} | {m_ov.n_iter_:17d} | {str(bool(m_ov.converged_)):19s} | {m_ov.score(X_ov):12.5f}\")",
