          "solution": "```python\nimport numpy as np\nfrom scipy.linalg import cholesky, solve_triangular\nfrom scipy.special import logsumexp\n\ndef em_one_step_elbo_audit(X, weights, means, covs, reg_covar: float = 1e-6) -> tuple[float, float, float, bool]:\n    X = np.asarray(X, dtype=float)\n    pis = np.asarray(weights, dtype=float).copy()\n    mus = np.asarray(means, dtype=float).copy()\n    covs = np.asarray(covs, dtype=float).copy()\n    n, d = X.shape\n    k = len(pis)\n    def log_joint(p, m, c):\n        lj = np.empty((n, k), dtype=float)\n        for j in range(k):\n            L = cholesky(c[j], lower=True)\n            ld = 2.0 * np.sum(np.log(np.diag(L)))\n            sol = solve_triangular(L, (X - m[j]).T, lower=True)\n            lj[:, j] = np.log(p[j]) - 0.5 * (d * np.log(2.0 * np.pi) + ld + np.sum(sol ** 2, axis=0))\n        return lj\n    lj0 = log_joint(pis, mus, covs)\n    lpx0 = logsumexp(lj0, axis=1)\n    ll_before = float(np.mean(lpx0))\n    gamma = np.exp(lj0 - lpx0[:, None])\n    elbo_e = float((np.sum(gamma * lj0) - np.sum(gamma * np.log(np.clip(gamma, 1e-300, 1.0)))) / n)\n    nk = np.sum(gamma, axis=0)\n    pis_new = nk / n\n    mus_new = (gamma.T @ X) / nk[:, None]\n    covs_new = np.empty_like(covs)\n    for j in range(k):\n        diff = X - mus_new[j]\n        covs_new[j] = (diff.T @ (diff * gamma[:, j : j + 1])) / nk[j] + reg_covar * np.eye(d)\n    lj1 = log_joint(pis_new, mus_new, covs_new)\n    ll_after = float(np.mean(logsumexp(lj1, axis=1)))\n    return (round(ll_before, 4), round(elbo_e, 4), round(ll_after, 4), bool(ll_after >= ll_before - 1e-10))\n```"
