          "code": "import numpy as np\nfrom sklearn.mixture import GaussianMixture\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(2333)\n\n# 1) Reproduksi Crash ValueError pada reg_covar=0.0 (Fitur Kolinear + Skala Campuran + Klaster Kecil)\n# Fitur 0: Pendapatan (Rp jutaan), Fitur 1: Rasio klik (0.01..0.12), Fitur 2: Fitur duplikat kolinear eksak!\ng0 = np.column_stack([rng.normal(12e6, 2.5e6, 90), rng.normal(0.04, 0.008, 90)])\ng1 = np.column_stack([rng.normal(45e6, 6.0e6, 80), rng.normal(0.09, 0.012, 80)])\ng2 = np.column_stack([rng.normal(85e6, 4.0e6, 8), rng.normal(0.14, 0.005, 8)])  # Klaster kecil\nX_base = np.vstack([g0, g1, g2])\n# Tambahkan kolom kolinear persis (sumber matriks singular rank-deficient di produksi!)\nX_bad = np.column_stack([X_base, 2.0 * X_base[:, 0], rng.normal(50.0, 5.0, len(X_base))])\n\nprint(\"=== 1. Reproduksi Kegagalan reg_covar=0.0 pada Data Kolinear & Skala Campuran ===\")\ntry:\n    GaussianMixture(n_components=3, covariance_type=\"full\", reg_covar=0.0, random_state=42).fit(X_bad)\n    print(\"Status reg_covar=0.0 : Selesai tanpa error\")\nexcept (ValueError, np.linalg.LinAlgError) as err:\n    print(f\"Status reg_covar=0.0 : CRASH {type(err).__name__} -> {str(err)[:78]}...\")\n\nX_scaled_bad = StandardScaler().fit_transform(X_bad)\ngm_safe = GaussianMixture(n_components=3, covariance_type=\"full\", reg_covar=1e-4, n_init=5, random_state=42).fit(X_scaled_bad)\nmin_eig_safe = min(float(np.min(np.linalg.eigvalsh(c))) for c in gm_safe.covariances_)\nprint(f\"Status StandardScaler + reg_covar=1e-4 : SUKSES | Converged={gm_safe.converged_} | Min Eigenvalue={min_eig_safe:.2e}\")\n\n# 2) Sweep Kalibrasi reg_covar pada Data Terstandardisasi d=25, N_train=180 (N_k ~ 60)\nmu_s = [np.zeros(25), np.r_[np.full(8, 1.8), np.zeros(17)], np.r_[np.zeros(8), np.full(8, -1.8), np.zeros(9)]]\nX_tr = np.vstack([rng.normal(m, 0.9, size=(60, 25)) for m in mu_s])\nX_te = np.vstack([rng.normal(m, 0.9, size=(60, 25)) for m in mu_s])\nscaler = StandardScaler().fit(X_tr)\nX_tr_s, X_te_s = scaler.transform(X_tr), scaler.transform(X_te)\n\nprint(\"\\n=== 2. Audit Kalibrasi reg_covar (full, d=25, N_train=180): Condition Number vs Held-Out LL ===\")\nprint(\"reg_covar | Min Eig   | Max Cond(Sigma) | Train LL | Held-Out Test LL | Gap Overfit\")\nprint(\"-\" * 86)\nfor reg in [1e-8, 1e-5, 1e-3, 1e-2, 1e-1, 5e-1]:\n    m = GaussianMixture(n_components=3, covariance_type=\"full\", reg_covar=reg, n_init=3, random_state=42).fit(X_tr_s)\n    eigs = [np.linalg.eigvalsh(c) for c in m.covariances_]\n    min_e = min(float(e[0]) for e in eigs)\n    max_cond = max(float(e[-1] / e[0]) for e in eigs)\n    tr_ll, te_ll = float(m.score(X_tr_s)), float(m.score(X_te_s))\n    print(f\"{reg:9.1e} | {min_e:9.2e} | {max_cond:15.1f} | {tr_ll:8.3f} | {te_ll:16.3f} | {tr_ll - te_ll:+11.3f}\")",
