          "code": "import numpy as np\nfrom sklearn.metrics import average_precision_score, roc_auc_score\nfrom sklearn.mixture import BayesianGaussianMixture, GaussianMixture\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(2343)\n\n# Telemetri 3 rezim operasi mesin industri (d=4: RPM, suhu, getaran_x, tekanan)\nmodes_mu = [\n    [-2.4, -1.8, 0.2, 0.0],\n    [2.4, -1.4, -0.5, 1.2],\n    [0.0, 2.8, 1.6, -1.4],\n]\nmodes_cov = [\n    np.array([[0.35, 0.22, 0.05, 0.02], [0.22, 0.30, 0.04, 0.01], [0.05, 0.04, 0.25, 0.02], [0.02, 0.01, 0.02, 0.28]]),\n    np.array([[0.40, -0.25, 0.03, 0.04], [-0.25, 0.32, 0.02, -0.02], [0.03, 0.02, 0.30, 0.03], [0.04, -0.02, 0.03, 0.26]]),\n    np.array([[0.30, 0.04, 0.18, -0.05], [0.04, 0.36, 0.05, -0.03], [0.18, 0.05, 0.28, -0.04], [-0.05, -0.03, -0.04, 0.30]]),\n]\n\nX_norm_tr = np.vstack([rng.multivariate_normal(m, c, size=200) for m, c in zip(modes_mu, modes_cov)])\nX_norm_val = np.vstack([rng.multivariate_normal(m, c, size=100) for m, c in zip(modes_mu, modes_cov)])\nX_norm_te = np.vstack([rng.multivariate_normal(m, c, size=100) for m, c in zip(modes_mu, modes_cov)])\n\n# 36 anomali halus: 20 di celah kosong antar-mode (tampak normal di marginal 1D!) + 16 anomali ekor\nanom_gap = rng.normal([0.0, 0.0, 0.3, 0.0], 0.45, size=(20, 4))\nanom_tail = rng.normal([3.6, 2.2, -2.2, 2.5], 0.50, size=(16, 4))\nX_test_all = np.vstack([X_norm_te, anom_gap, anom_tail])\ny_anom = np.array([0] * len(X_norm_te) + [1] * (len(anom_gap) + len(anom_tail)))\n\nscaler = StandardScaler().fit(X_norm_tr)\nXtr_s = scaler.transform(X_norm_tr)\nXval_s = scaler.transform(X_norm_val)\nXte_s = scaler.transform(X_test_all)\n\n# 1) Audit Sensitivitas Prior Konsentrasi alpha_0 pada Dirichlet Process BGMM\nprint(\"=== 1. Sensitivitas Prior Konsentrasi weight_concentration_prior (alpha_0) pada DP-BGMM (K_max=10) ===\")\nprint(\" alpha_0 | Aktif (w>0.01) | K_eff = exp(H(w)) | Val Avg LL\")\nprint(\"-\" * 60)\nfor alpha0 in [0.001, 0.05, 1.0, 15.0, 100.0]:\n    vb = BayesianGaussianMixture(\n        n_components=10,\n        covariance_type=\"full\",\n        weight_concentration_prior_type=\"dirichlet_process\",\n        weight_concentration_prior=alpha0,\n        n_init=2,\n        max_iter=200,\n        random_state=42,\n    ).fit(Xtr_s)\n    w = np.clip(vb.weights_, 1e-15, 1.0)\n    k_eff = float(np.exp(-np.sum(w * np.log(w))))\n    n_act = int(np.sum(vb.weights_ > 0.01))\n    print(f\" {alpha0:7.3f} | {n_act:14d} | {k_eff:17.2f} | {vb.score(Xval_s):10.4f}\")\n\n# 2) Deteksi Anomali Multi-Mode via GMM Log-Density score_samples() vs Single Gaussian\nsingle_g = GaussianMixture(n_components=1, covariance_type=\"full\", random_state=42).fit(Xtr_s)\nmulti_g = min(\n    (GaussianMixture(n_components=k, covariance_type=\"full\", n_init=3, random_state=42).fit(Xtr_s) for k in range(1, 7)),\n    key=lambda m: m.bic(Xtr_s),\n)\n\nprint(\"\\n=== 2. Deteksi Anomali Multi-Mode (Kalibrasi Ambang Kuantil-2% pada Validasi Bersih) ===\")\nprint(\"Model Densitas           | ROC-AUC | PR-AUC | Recall Anomali | Recall Celah-Mode | FPR Normal\")\nprint(\"-\" * 96)\nfor name, model in [(\"Single Gaussian (K=1)\", single_g), (f\"BIC-GMM (K={multi_g.n_components})\", multi_g)]:\n    val_ll = model.score_samples(Xval_s)\n    tau = float(np.percentile(val_ll, 2.0))\n    te_ll = model.score_samples(Xte_s)\n    anom_score = -te_ll  # Semakin kecil log-density -> semakin tinggi skor anomali\n    preds_anom = (te_ll < tau).astype(int)\n    roc = float(roc_auc_score(y_anom, anom_score))\n    pr = float(average_precision_score(y_anom, anom_score))\n    rec_all = float(np.mean(preds_anom[y_anom == 1]))\n    rec_gap = float(np.mean(preds_anom[len(X_norm_te) : len(X_norm_te) + len(anom_gap)]))\n    fpr = float(np.mean(preds_anom[y_anom == 0]))\n    print(f\"{name:24s} | {roc:7.4f} | {pr:6.4f} | {100*rec_all:13.1f}% | {100*rec_gap:16.1f}% | {100*fpr:9.2f}%\")",
